// Package fs provides unified local file access for native apps and container apps.
//
// What is unified is not the "path" but **logical addressing**: an app addresses by
// (space, pool, relative path) or by UFI, which the runtime-injected mount table
// resolves into an absolute path that the current process can open directly. So both
// sides are ordinary POSIX calls — no HTTP round trip, no server-side file handle,
// and mmap/sqlite/sendfile all work.
//
// The mount table is generated by the daemon:
//
//   - container: /etc/miniruntime/resources/mounts.json (read-only bind)
//   - native: <state>/<appcode>/mounts.json, with the path injected via MINI_APP_MOUNT_TABLE
//
// See docs/technical/FS_ACCESS.md for details.
package fs

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/siyouyun-open/siyouyun_sdk/v2/protocol"
)

// Predictable errors. Callers check them with errors.Is.
var (
	ErrNoMountTable = errors.New("fs: mount table not found")
	ErrNoMount      = errors.New("fs: mount not found")
	ErrAmbiguous    = errors.New("fs: mount name is ambiguous across spaces")
	ErrBadUFI       = errors.New("fs: invalid ufi")
	ErrEscape       = errors.New("fs: path escapes the mount root")
	ErrReadOnly     = errors.New("fs: mount is read-only")
	// ErrOutOfScope reports that the path is outside the app's declared data access scope.
	ErrOutOfScope = errors.New("fs: path is outside the declared storage scope")
)

// Table is a parsed mount table.
type Table struct {
	// source is the mount table file path, used only for troubleshooting.
	source  string
	appData *Mount
	pools   []*Mount
	// spaces is the authorization list injected by the daemon: user spaces this instance
	// may serve, beyond appData.space and the pool spaces. It adds no mount point; it only
	// widens Spaces() (see the Spaces doc comment).
	spaces []string
	// scopes is the data access scope injected by the daemon (used to narrow native); empty means none was declared.
	scopes []protocol.ScopeValue
}

// Mount represents a local directory that can be accessed directly.
type Mount struct {
	name     string
	space    string
	root     string
	realRoot string
	writable bool
	kind     string
}

// Load locates and parses the mount table according to the runtime convention:
// it checks MINI_APP_MOUNT_TABLE first (native), then falls back to the fixed path inside the container.
func Load() (*Table, error) {
	if path := strings.TrimSpace(os.Getenv(protocol.EnvMountTable)); path != "" {
		return LoadFile(path)
	}
	return LoadFile(filepath.Join(protocol.ContainerResourceDir, protocol.MountTableFileName))
}

// LoadFile parses the mount table at the given path.
func LoadFile(path string) (*Table, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("%w: %s", ErrNoMountTable, path)
		}
		return nil, fmt.Errorf("fs: read mount table %s: %w", path, err)
	}
	var raw protocol.MountTable
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("fs: parse mount table %s: %w", path, err)
	}
	if raw.Version != 0 && raw.Version != protocol.MountTableVersion {
		return nil, fmt.Errorf("fs: unsupported mount table version %d (want %d)", raw.Version, protocol.MountTableVersion)
	}

	table := &Table{source: path}
	if raw.AppData != nil {
		if mount, ok := newMount(*raw.AppData); ok {
			table.appData = mount
		}
	}
	for _, entry := range raw.Pools {
		if mount, ok := newMount(entry); ok {
			table.pools = append(table.pools, mount)
		}
	}
	// Explicit authorization list: it carries no path (there is nothing to open), so it is
	// carried over as-is and only widens Spaces(). Blank entries add nothing.
	table.spaces = append(table.spaces, raw.Spaces...)
	// Scope declarations: invalid values are skipped (the daemon-side declaration has
	// already been validated; this is only defensive). When none remain, no narrowing is
	// applied — turning "failed to parse the declaration" into "reject everything" would
	// leave the app completely unable to read files, whereas the real security boundary is
	// that the daemon mounts only authorized spaces, plus deploy-time declaration validation.
	for _, raw := range raw.Scopes {
		if value, err := protocol.ParseScopeValue(raw); err == nil {
			table.scopes = append(table.scopes, value)
		}
	}
	return table, nil
}

func newMount(entry protocol.MountEntry) (*Mount, bool) {
	root := strings.TrimSpace(entry.LocalPath)
	if root == "" {
		return nil, false
	}
	kind := strings.TrimSpace(entry.Kind)
	if kind == "" {
		kind = protocol.MountKindPool
	}
	mount := &Mount{
		name:     strings.TrimSpace(entry.Name),
		space:    strings.TrimSpace(entry.Space),
		root:     root,
		writable: entry.Writable,
		kind:     kind,
	}
	// The real root is used to prevent symlink escapes: the mount point itself may be a symlink.
	if resolved, err := filepath.EvalSymlinks(root); err == nil && resolved != "" {
		mount.realRoot = resolved
	} else {
		mount.realRoot = root
	}
	return mount, true
}

// Source returns the mount table file path (for troubleshooting).
func (t *Table) Source() string {
	if t == nil {
		return ""
	}
	return t.source
}

// AppData returns the app's private persistent directory (storage.app.file).
func (t *Table) AppData() (*Mount, error) {
	if t == nil || t.appData == nil {
		return nil, fmt.Errorf("%w: app data directory (declare storage.app.file)", ErrNoMount)
	}
	return t.appData, nil
}

// Pools returns all storage pools (in the same order as the mount table).
func (t *Table) Pools() []*Mount {
	if t == nil {
		return nil
	}
	return append([]*Mount(nil), t.pools...)
}

// Spaces returns the user spaces the instance is authorized to serve (deduplicated and sorted).
//
// It is the union of three sources:
//
//   - AppData.Space — the application's private space;
//   - Pools[].Space — the spaces the storage pools belong to;
//   - MountTable.Spaces — the runtime's explicit authorization list.
//
// The third source exists because AppData is a single pointer: a shared native instance
// whose data space is `default` cannot express the user spaces it serves through
// AppData/Pools alone (it may have no pool at all), and every call would then be
// rejected here.
func (t *Table) Spaces() []string {
	if t == nil {
		return nil
	}
	seen := map[string]struct{}{}
	var spaces []string
	add := func(space string) {
		if space == "" {
			return
		}
		if _, ok := seen[space]; ok {
			return
		}
		seen[space] = struct{}{}
		spaces = append(spaces, space)
	}
	add(t.appDataSpace())
	for _, pool := range t.pools {
		add(pool.space)
	}
	for _, space := range t.spaces {
		add(strings.TrimSpace(space))
	}
	sort.Strings(spaces)
	return spaces
}

func (t *Table) appDataSpace() string {
	if t.appData == nil {
		return ""
	}
	return t.appData.space
}

// HasSpace reports whether a user space appears in the mount table, i.e. whether the
// instance is authorized to see it.
//
// This is the criterion for app-side space authorization: native is a shared instance
// that "installs once and serves many spaces", so the space carried in a request must
// fall within the authorized set; otherwise data would be written to or read from
// **another user's** space. The mount table is generated by the daemon from the
// authorized spaces completed for the currently logged-in user, so this set is the
// authoritative source.
func (t *Table) HasSpace(space string) bool {
	space = strings.TrimSpace(space)
	if space == "" {
		return false
	}
	for _, s := range t.Spaces() {
		if s == space {
			return true
		}
	}
	return false
}

// SpacePools returns the storage pools under a given user space (the app's private directory is not counted as a pool).
func (t *Table) SpacePools(space string) []*Mount {
	space = strings.TrimSpace(space)
	if space == "" {
		return nil
	}
	var out []*Mount
	for _, pool := range t.pools {
		if pool.space == space {
			out = append(out, pool)
		}
	}
	return out
}

// Pool resolves by pool name. It returns ErrAmbiguous when the name is duplicated across
// user spaces — silently taking the first would write data into someone else's space,
// so this must fail.
func (t *Table) Pool(name string) (*Mount, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return nil, fmt.Errorf("%w: empty pool name", ErrNoMount)
	}
	var found *Mount
	for _, pool := range t.Pools() {
		if pool.name != name {
			continue
		}
		if found != nil {
			return nil, fmt.Errorf("%w: pool %q exists in spaces %q and %q; use PoolIn", ErrAmbiguous, name, found.space, pool.space)
		}
		found = pool
	}
	if found == nil {
		return nil, fmt.Errorf("%w: %s", ErrNoMount, name)
	}
	return found, nil
}

// PoolIn resolves exactly by (user space, pool name); multi-space instances must use it.
func (t *Table) PoolIn(space, name string) (*Mount, error) {
	space = strings.TrimSpace(space)
	name = strings.TrimSpace(name)
	for _, pool := range t.Pools() {
		if pool.name == name && pool.space == space {
			return pool, nil
		}
	}
	return nil, fmt.Errorf("%w: %s in space %q", ErrNoMount, name, space)
}

// LocalPath resolves a UFI into a local absolute path.
func (t *Table) LocalPath(ufi string) (string, error) {
	poolName, rel, err := ParseUFI(ufi)
	if err != nil {
		return "", err
	}
	pool, err := t.Pool(poolName)
	if err != nil {
		return "", err
	}
	if !t.inScope(pool.space, rel) {
		return "", fmt.Errorf("%w: %s", ErrOutOfScope, ufi)
	}
	return pool.Resolve(rel)
}

// Scopes returns the data access scopes declared in the mount table (used to narrow native); containers usually have none.
func (t *Table) Scopes() []protocol.ScopeValue {
	if t == nil {
		return nil
	}
	return append([]protocol.ScopeValue(nil), t.scopes...)
}

// InScope reports whether a UFI falls within the declared data access scope.
//
// The app's **full reconciliation** path must use it: the event path has already been
// filtered by the daemon under the same set of rules, so if reconciliation used a
// different judgment there would be churn where "an event was received but reconciliation
// cleared it again" (or the opposite: missed events).
func (t *Table) InScope(ufi string) bool {
	poolName, rel, err := ParseUFI(ufi)
	if err != nil {
		return false
	}
	pool, err := t.Pool(poolName)
	if err != nil {
		return false
	}
	return t.inScope(pool.space, rel)
}

// InScopeIn evaluates under a specified user space (use it to disambiguate when pools share a name across spaces).
func (t *Table) InScopeIn(space, ufi string) bool {
	poolName, rel, err := ParseUFI(ufi)
	if err != nil {
		return false
	}
	if _, err := t.PoolIn(space, poolName); err != nil {
		return false
	}
	return t.inScope(space, rel)
}

// inScope reports whether "the relative path rel inside the pool belonging to space"
// falls within the declared scope.
//
// The semantics match the daemon's fan-out filtering (the same protocol-layer rules):
//   - no declaration → unrestricted (behavior for old packages/old daemons is unchanged);
//   - `space[.path]`: the space of that pool must be in this table's space set, then judge by path prefix;
//   - `all[.path]`: the space axis is fully allowed, judge by path only;
//   - `app`: the private directory does not go through a pool UFI, so it is ignored here.
func (t *Table) inScope(space, rel string) bool {
	if len(t.scopes) == 0 {
		return true
	}
	for _, scope := range t.scopes {
		switch scope.Space {
		case protocol.ScopeSpaceAll:
		case protocol.ScopeSpaceOwn:
			if space != "" && !t.HasSpace(space) {
				continue
			}
		default:
			continue
		}
		want, ok := scope.ScopeKeyPath()
		if !ok {
			continue
		}
		if protocol.PathWithin(want, rel) {
			return true
		}
	}
	return false
}

// LocalPathIn resolves a UFI into a local absolute path within the specified user space.
func (t *Table) LocalPathIn(space, ufi string) (string, error) {
	poolName, rel, err := ParseUFI(ufi)
	if err != nil {
		return "", err
	}
	pool, err := t.PoolIn(space, poolName)
	if err != nil {
		return "", err
	}
	if !t.inScope(space, rel) {
		return "", fmt.Errorf("%w: %s (space %q)", ErrOutOfScope, ufi, space)
	}
	return pool.Resolve(rel)
}

// LocalPathForUGN uses the UGN carried by an event to fill in the user space before
// resolving the UFI.
//
// A UFI itself does not contain the user space, and multiple spaces may have pools with
// the same name; an event carries the UGN as well, so only together can the two uniquely
// determine a local path.
func (t *Table) LocalPathForUGN(username, groupName, namespace, ufi string) (string, error) {
	return t.LocalPathIn(DeploySpace(username, groupName, namespace), ufi)
}

// DeploySpace computes the deploy space identifier from the UGN.
//
// Consistent with the daemon's rules: personal space {username}-{namespace}, group space {groupname}-{namespace}.
func DeploySpace(username, groupName, namespace string) string {
	owner := strings.TrimSpace(username)
	if group := strings.TrimSpace(groupName); group != "" && group != owner {
		owner = group
	}
	namespace = strings.TrimSpace(namespace)
	switch {
	case owner == "":
		return namespace
	case namespace == "":
		return owner
	default:
		return owner + "-" + namespace
	}
}

// ParseUFI splits out the pool name and relative path of a UFI.
// Of the form /ufi/pool-raw/<pool>[/<rel>]; it returns ErrBadUFI when it cannot be parsed.
func ParseUFI(ufi string) (string, string, error) {
	raw := strings.TrimSpace(ufi)
	if !strings.HasPrefix(raw, protocol.UFIPoolPrefix) {
		return "", "", fmt.Errorf("%w: %s", ErrBadUFI, ufi)
	}
	rest := strings.TrimPrefix(raw, protocol.UFIPoolPrefix)
	if rest == "" {
		return "", "", fmt.Errorf("%w: %s", ErrBadUFI, ufi)
	}
	if idx := strings.IndexByte(rest, '/'); idx >= 0 {
		pool := rest[:idx]
		rel := strings.TrimLeft(rest[idx+1:], "/")
		if pool == "" {
			return "", "", fmt.Errorf("%w: %s", ErrBadUFI, ufi)
		}
		return pool, rel, nil
	}
	return rest, "", nil
}

// UFI builds a UFI from a pool name and a relative path.
func UFI(pool, rel string) string {
	pool = strings.TrimSpace(pool)
	rel = strings.TrimLeft(strings.TrimSpace(rel), "/")
	if rel == "" {
		return protocol.UFIPoolPrefix + pool
	}
	return protocol.UFIPoolPrefix + pool + "/" + rel
}

// Name / Space / Root / Writable / Kind are the read-only properties of Mount.
func (m *Mount) Name() string  { return m.name }
func (m *Mount) Space() string { return m.space }
func (m *Mount) Root() string  { return m.root }
func (m *Mount) Writable() bool {
	return m != nil && m.writable
}
func (m *Mount) Kind() string { return m.kind }

// String is convenient for log and test output.
func (m *Mount) String() string {
	if m == nil {
		return "<nil mount>"
	}
	return fmt.Sprintf("%s{space=%s root=%s writable=%v}", m.kind, m.space, m.root, m.writable)
}
